#if UNITY_EDITOR
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
namespace DeliveryService.Mok.Editor {
public static class SyntyStoryUpgrade {
 public static void Inspect(){string s="";foreach(var path in new[]{"Assets/Synty/PolygonCity/Prefabs/Characters/Character_Male_Jacket.prefab","Assets/Synty/PolygonCity/Prefabs/Characters/Character_BusinessMan_Suit.prefab","Assets/Synty/PolygonHeist/Prefab/Characters/SM_Chr_Male_Overall_01.prefab","Assets/Synty/PolygonHeist/Prefab/Characters/SM_Chr_Male_SuitVest_01.prefab"}){var g=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));try{var a=g.GetComponentInChildren<Animator>();s+=path+" animator="+(a?a.name:"none")+" human="+(a&&a.isHuman)+" scale="+g.transform.localScale+"\n";foreach(var r in g.GetComponentsInChildren<SkinnedMeshRenderer>())s+="mesh "+r.name+" bounds="+r.bounds+" bones="+string.Join(",",r.bones.Select(b=>b.name))+" materials="+string.Join(",",r.sharedMaterials.Select(m=>m.name+":"+m.shader.name))+"\n";}finally{UnityEngine.Object.DestroyImmediate(g);}}
 var f=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();var roots=new[]{f.target,f.contact,f.driver,f.preparation.mechanic,f.preparation.preparation.delivery.broker.broker,UnityEngine.Object.FindFirstObjectByType<StoryTutorial>().actor};foreach(var root in roots){var a=root.GetComponentInChildren<Animator>(true);s+="SCENE "+root.name+" scale="+root.lossyScale+" animator="+a.name+" human="+a.isHuman+"\n";foreach(var r in root.GetComponentsInChildren<Renderer>(true))s+=r.name+" "+r.GetType().Name+" "+r.bounds+"\n";}File.WriteAllText("Logs/Synty-story-inspect.txt",s);}
 const string Art="Assets/Scripts/Mok/Art/SyntyStory";
 const string City="Assets/Synty/PolygonCity/Prefabs/Characters/";
 const string Heist="Assets/Synty/PolygonHeist/Prefab/Characters/";
 const string Props="Assets/Synty/PolygonHeist/Prefab/Props/";
 static string report;
 // 게임플레이 뼈대와 레그돌 참조는 유지하고, Synty 스킨을 현재 뼈대에 저장해 연결한다.
 public static void Skin(Transform root,string path,string key,bool keepBag=false,bool poseMatch=false){
  var target=root.GetComponentInChildren<Animator>(true);if(!target||!target.isHuman)throw new Exception("Missing humanoid "+root.name);
  var dest=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).First(r=>r.sharedMesh&&r.sharedMesh.boneWeights.Length>0);
  var source=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));try{
   var a=source.GetComponentInChildren<Animator>();var renderer=source.GetComponentInChildren<SkinnedMeshRenderer>();if(!a||!a.isHuman||!renderer)throw new Exception("Missing source rig "+path);
   if(poseMatch){a.runtimeAnimatorController=target.runtimeAnimatorController;a.enabled=true;target.enabled=true;target.Rebind();target.Update(0);a.Rebind();a.Play("Idle",0,0);a.Update(.1f);var idle=target.runtimeAnimatorController.animationClips.First(c=>c.name.ToLowerInvariant().Contains("idle"));AnimationMode.StartAnimationMode();AnimationMode.BeginSampling();AnimationMode.SampleAnimationClip(source,idle,0);AnimationMode.EndSampling();}

   source.transform.SetPositionAndRotation(root.position,root.rotation);var fit=dest.bounds;if(root.GetComponent<PlayerAvatar>())foreach(var r in root.GetComponentsInChildren<SkinnedMeshRenderer>())fit.Encapsulate(r.bounds);float scale=fit.size.y/renderer.bounds.size.y;if(poseMatch){float th=target.GetBoneTransform(HumanBodyBones.Head).position.y-target.GetBoneTransform(HumanBodyBones.LeftFoot).position.y;float sh=a.GetBoneTransform(HumanBodyBones.Head).position.y-a.GetBoneTransform(HumanBodyBones.LeftFoot).position.y;scale=th/sh;}source.transform.localScale*=scale;source.transform.position+=Vector3.up*(poseMatch?target.GetBoneTransform(HumanBodyBones.LeftFoot).position.y-a.GetBoneTransform(HumanBodyBones.LeftFoot).position.y:fit.min.y-renderer.bounds.min.y);
   var map=new Dictionary<Transform,Transform>();for(int i=0;i<(int)HumanBodyBones.LastBone;i++){var from=a.GetBoneTransform((HumanBodyBones)i);var to=target.GetBoneTransform((HumanBodyBones)i);if(from&&to)map[from]=to;}map[a.transform]=target.transform;
   Transform Match(Transform bone){for(var t=bone;t;t=t.parent)if(map.TryGetValue(t,out var match))return match;return target.transform;}
   var mesh=UnityEngine.Object.Instantiate(renderer.sharedMesh);mesh.name="Synty "+key;if(poseMatch){var original=renderer.sharedMesh;var vertices=original.vertices;var normals=original.normals;var weights=original.boneWeights;var matrices=renderer.bones.Select((b,i)=>dest.transform.worldToLocalMatrix*b.localToWorldMatrix*original.bindposes[i]).ToArray();for(int i=0;i<vertices.Length;i++){var w=weights[i];var v=vertices[i];var n=normals[i];vertices[i]=matrices[w.boneIndex0].MultiplyPoint3x4(v)*w.weight0+matrices[w.boneIndex1].MultiplyPoint3x4(v)*w.weight1+matrices[w.boneIndex2].MultiplyPoint3x4(v)*w.weight2+matrices[w.boneIndex3].MultiplyPoint3x4(v)*w.weight3;normals[i]=(matrices[w.boneIndex0].MultiplyVector(n)*w.weight0+matrices[w.boneIndex1].MultiplyVector(n)*w.weight1+matrices[w.boneIndex2].MultiplyVector(n)*w.weight2+matrices[w.boneIndex3].MultiplyVector(n)*w.weight3).normalized;}mesh.vertices=vertices;mesh.normals=normals;}

   var conversion=poseMatch?Matrix4x4.identity:dest.transform.worldToLocalMatrix*renderer.transform.localToWorldMatrix;mesh.vertices=mesh.vertices.Select(v=>conversion.MultiplyPoint3x4(v)).ToArray();var normalMatrix=conversion.inverse.transpose;mesh.normals=mesh.normals.Select(n=>normalMatrix.MultiplyVector(n).normalized).ToArray();mesh.tangents=mesh.tangents.Select(t=>{var v=conversion.MultiplyVector(new Vector3(t.x,t.y,t.z)).normalized;return new Vector4(v.x,v.y,v.z,t.w);}).ToArray();
   var bones=renderer.bones.Select(Match).ToArray();mesh.bindposes=bones.Select(b=>b.worldToLocalMatrix*dest.transform.localToWorldMatrix).ToArray();mesh.RecalculateBounds();if(poseMatch)File.AppendAllText("Logs/Skin-final-debug.txt",key+" bounds "+mesh.bounds+" animatorUpper "+a.GetBoneTransform(HumanBodyBones.LeftUpperArm).position+" rendererUpper "+string.Join(";",renderer.bones.Where(b=>b.name.Contains("Shoulder")||b.name.Contains("Elbow")).Select(b=>b.name+":"+b.position))+"\n");var asset=Art+"/"+key+".asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(asset);if(saved){EditorUtility.CopySerialized(mesh,saved);UnityEngine.Object.DestroyImmediate(mesh);mesh=saved;EditorUtility.SetDirty(mesh);}else AssetDatabase.CreateAsset(mesh,asset);
   dest.sharedMesh=mesh;dest.bones=bones;dest.rootBone=target.GetBoneTransform(HumanBodyBones.Hips);dest.sharedMaterials=renderer.sharedMaterials;dest.localBounds=mesh.bounds;dest.enabled=true;dest.updateWhenOffscreen=true;EditorUtility.SetDirty(dest);
   foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true)){string n=r.name;if(n.StartsWith("Mingi ")||n.StartsWith("Broker ")||n.StartsWith("Gang ")||n.StartsWith("Mechanic ")||n=="Catering staff badge"||(!keepBag&&(n.StartsWith("Bag ")||n.StartsWith("Stored cash")||n=="Front strap"||n=="Shoulder strap"||n=="Carry handle"||n=="Zipper seam"||n=="Cash in hand")))r.enabled=false;}
   report+="CHARACTER "+root.name+" <- "+path+"; bones="+bones.Length+"\n";
  }finally{if(poseMatch&&AnimationMode.InAnimationMode())AnimationMode.StopAnimationMode();UnityEngine.Object.DestroyImmediate(source);}
 }
 static GameObject Prop(string path,Transform parent,Vector3 at,Vector3 size,Quaternion rotation){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path));g.transform.SetParent(parent,false);g.transform.localRotation=rotation;var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);float scale=Mathf.Min(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z);g.transform.localScale*=scale;b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);g.transform.position+=parent.TransformPoint(at)-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);report+="PROP "+path+"\n";return g;}
 public static void Apply(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();var scene=m.gameObject.scene;var stamp=DateTime.Now.ToString("yyyyMMdd-HHmmss");if(!EditorSceneManager.SaveScene(scene,"Logs/JJinCity-before-synty-"+stamp+".unity",true))throw new Exception("Backup failed");Directory.CreateDirectory(Art);AssetDatabase.Refresh();report="Synty story model replacements\n";
  var broker=m.preparation.preparation.delivery.broker;var tutorial=UnityEngine.Object.FindFirstObjectByType<StoryTutorial>();
  Skin(tutorial.actor,City+"Character_Male_Jacket.prefab","Mingi",true);Skin(broker.broker,Heist+"SM_Chr_Male_SuitVest_01.prefab","Broker");Skin(m.target,City+"Character_BusinessMan_Suit.prefab","Jinwoong");Skin(m.contact,City+"Character_BusinessMan_Shirt.prefab","Contact");Skin(m.preparation.mechanic,Heist+"SM_Chr_Male_Overall_01.prefab","Mechanic");Skin(m.driver,Heist+"SM_Chr_Male_Overall_01.prefab","MechanicDriver");Skin(m.preparation.preparation.delivery.attendant,Heist+"SM_Chr_Male_Shirt_01.prefab","Attendant");
  int n=0;foreach(var enemy in new[]{broker.enemyTemplate,m.preparation.enemyTemplate}.Distinct())Skin(enemy.transform,City+"Character_Male_Jacket.prefab","Gang"+(n++));
  n=0;foreach(var a in m.actors.GetComponentsInChildren<Animator>(true)){if(a.transform==m.target||a.transform==m.contact)continue;Skin(a.transform,n%2==0?City+"Character_BusinessMan_Suit.prefab":Heist+"SM_Chr_Male_SuitVest_01.prefab","Guest"+(n++));}
  var w=m.interior.transform;var old=w.Find("Synty furnished reception");if(old)UnityEngine.Object.DestroyImmediate(old.gameObject);var group=new GameObject("Synty furnished reception").transform;group.SetParent(w,false);
  var replace=new HashSet<string>{"Banquet table","Banquet plinth","Guest chair seat","Guest chair back","Table centerpiece","Service table","Service storage","Planter","Decorative foliage","Supply rack","Catering crate","Laundry trolley","Folded towels"};foreach(var r in w.GetComponentsInChildren<MeshRenderer>(true))if(replace.Contains(r.name))r.enabled=false;
  for(int i=0;i<3;i++){float z=1+i*4;Prop(Props+"SM_Prop_Table_02.prefab",group,new Vector3(5,0,z),new Vector3(2.1f,.9f,1.5f),Quaternion.identity);foreach(float side in new[]{-1f,1f})Prop(Props+"SM_Prop_Seat_01.prefab",group,new Vector3(5+side*1.6f,0,z),new Vector3(.65f,1.2f,.7f),Quaternion.Euler(0,side<0?90:-90,0));Prop(Props+"SM_Prop_Plant_01.prefab",group,new Vector3(5,.92f,z),new Vector3(.3f,.4f,.3f),Quaternion.identity);}
  Prop(Props+"SM_Prop_Desk_01.prefab",group,new Vector3(-3,0,-9),new Vector3(2,.93f,1.1f),Quaternion.identity);Prop(Props+"SM_Prop_Shelf_01.prefab",group,new Vector3(7,0,-10),new Vector3(3,2,1.2f),Quaternion.identity);Prop(Props+"SM_Prop_Shelf_01.prefab",group,new Vector3(.7f,0,-12.5f),new Vector3(2.8f,2,.6f),Quaternion.identity);Prop(Props+"SM_Prop_VaultTrolley_01.prefab",group,new Vector3(7.25f,0,-18),new Vector3(.65f,1.4f,1.2f),Quaternion.identity);
  foreach(var at in new[]{new Vector3(-8.7f,0,1),new Vector3(8.6f,0,11.6f)})Prop(Props+"SM_Prop_Plant_03.prefab",group,at,new Vector3(1.1f,1.8f,1.1f),Quaternion.identity);
  Prop(Props+"SM_Prop_Couch_01.prefab",group,new Vector3(-8.8f,0,4),new Vector3(1.1f,1.2f,2.3f),Quaternion.Euler(0,90,0));Prop(Props+"SM_Prop_WaterCooler_01.prefab",group,new Vector3(8.9f,0,-6),new Vector3(.7f,1.5f,.7f),Quaternion.identity);
  EditorSceneManager.MarkSceneDirty(scene);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene);VenueUpgrade.Validate();VenueFinaleBuilder.Preview();
  var bank=EditorSceneManager.OpenScene(BankPrologueBuilder.ScenePath,OpenSceneMode.Additive);try{if(!EditorSceneManager.SaveScene(bank,"Logs/Bank-before-synty-"+stamp+".unity",true))throw new Exception("Bank backup failed");var d=bank.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<BankPrologue>(true)).Single();Skin(d.accomplice.transform,City+"Character_Male_Jacket.prefab","MingiPrologue",true);Skin(d.shopArrival.actor,City+"Character_Male_Jacket.prefab","MingiArrival",true);EditorSceneManager.MarkSceneDirty(bank);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(bank);}finally{EditorSceneManager.CloseScene(bank,true);}File.WriteAllText("Logs/Synty-story-apply.txt",report);
 }

 public static void Refine(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();if(EditorApplication.isPlaying)throw new Exception("Edit mode required");EditorSceneManager.SaveScene(m.gameObject.scene,"Logs/JJinCity-before-synty-fit-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);report="Synty furniture and guard refinement\n";
 var group=m.interior.transform.Find("Synty furnished reception");foreach(Transform t in group){float height=t.name.Contains("Table_02")?.9f:t.name.Contains("Desk_01")?.93f:0;if(height<=0)continue;var rs=t.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);float floor=b.min.y;var scale=t.localScale;scale.y*=height/b.size.y;t.localScale=scale;b=rs[0].bounds;foreach(var r in rs)b.Encapsulate(r.bounds);t.position+=Vector3.up*(floor-b.min.y);}
 Skin(m.entryGuard,Heist+"SM_Chr_Male_SuitVest_01.prefab","EntryGuard");int i=0;foreach(var g in m.preparation.preparation.guards)Skin(g.transform,Heist+"SM_Chr_Male_SuitVest_01.prefab","PatrolGuard"+(i++));AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(m.gameObject.scene);EditorSceneManager.SaveScene(m.gameObject.scene);VenueUpgrade.Validate();VenueFinaleBuilder.Preview();File.WriteAllText("Logs/Synty-story-refine.txt",report);}

}}
#endif
